def DLWContract.SemiPair : ℝ → ℝ → DLWContract.Lattice → DLWContract.Lattice → Prop :=
fun a h F G => ∀ (j : ℤ), bil (a - h / 2) (F j) (G j) = 0 ∧ bil (a + h / 2) (F j) (G (j + 1)) = 0
def DLWContract.physU : DLWContract.Lattice → DLWContract.Lattice → DLWContract.Lattice :=
fun F G => lx (2 * logL F - logL G - fun j => logL G (j + 1))
def DLWContract.ReportUW.omega : DLWContract.Lattice → DLWContract.Lattice :=
fun G => lx (Sh (logL G) - logL G)
DLWContract.ReportUW.physical_v (h : ℝ) (F G : DLWContract.Lattice) : physV h F G = vFromOmega h (physU F G) (omega G)
